"use client";

import { cn } from "@/lib/utils";
import { PriceChart } from "@/components/moneytrees/charts/price-chart";
import { RangeSelector, usePrefersReducedMotion } from "@/components/moneytrees/charts/chart-engine";
import { Sparkline, type TickerPoint } from "@/components/moneytrees/sparkline";

export { Sparkline, type TickerPoint };

const defaultFormatTime = (ms: number) =>
  new Date(ms).toLocaleDateString(undefined, { month: "short", day: "numeric" });

type Props = {
  data: TickerPoint[];
  variant?: "sparkline" | "full";
  className?: string;
  height?: number;
  symbol?: string;
  name?: string;
  formatTime?: (ms: number) => string;
  formatPrice?: (n: number) => string;
};

export function TickerChart({
  data,
  variant = "sparkline",
  className,
  height,
  symbol = "",
  name = "",
  formatTime = defaultFormatTime,
}: Props) {
  if (variant === "full") {
    return (
      <PriceChart
        data={data.map((p) => ({ time: formatTime(p.time), price: p.price }))}
        symbol={symbol}
        name={name}
        compact
        className={cn("h-auto", className)}
        height={height ?? 280}
      />
    );
  }
  return <Sparkline data={data} className={className} height={height ?? 40} />;
}

type TimeRangeProps<R extends string> = {
  value: R;
  ranges: readonly R[];
  onChange: (r: R) => void;
  className?: string;
};

export function TimeRangeSelector<R extends string>({
  value,
  ranges,
  onChange,
  className,
}: TimeRangeProps<R>) {
  const reduce = usePrefersReducedMotion();
  return (
    <div className={className}>
      <RangeSelector
        ranges={ranges.map((label) => ({ label, bars: null }))}
        value={value}
        onChange={(label) => onChange(label as R)}
        reduce={reduce}
      />
    </div>
  );
}
